 static string CopyOfficial(string source,string destination){Directory.CreateDirectory(destination);foreach(string name in new[]{"index.html","webgal-engine.json"})Files.CopyFile(Path.Combine(source,name),Path.Combine(destination,name));string html=File.ReadAllText(Path.Combine(source,"index.html"));var match=Regex.Match(html,"<script\\b(?=[^>]*\\btype=['\"]module['\"])[^>]*\\bsrc=['\"]([^'\"]+)['\"]",RegexOptions.IgnoreCase);if(!match.Success)throw new Exception("Official fixture module not found");string relative=Regex.Split(match.Groups[1].Value,"[?#]")[0].TrimStart('.','/');Files.CopyFile(Files.Under(source,relative),Files.Under(destination,relative));return relative;}
