  Case(owned,realProject,"strict official 464",root464,"webgal",true,"open-webgal.webgal","4.6.4","4.6.4");Case(owned,realProject,"strict official 466",root466,"webgal",true,"open-webgal.webgal","4.6.6","4.6.6");Case(owned,realProject,"strict invalid engine identity",root466,"webgal",true,"webgal-mygo.mygo","3.2.1","4.6.4");Case(owned,realProject,"strict wrong bound version",root466,"webgal",true,"open-webgal.webgal","4.6.4","4.6.4");Case(owned,realProject,"strict unknown raw",custom464,"webgal",true,"open-webgal.webgal","4.6.4","4.6.4");Case(owned,realProject,"strict MyGO structural CPU fixture",mygo,"mygo",true,"webgal-mygo.mygo","3.2.1","4.6.4");Case(owned,realProject,"unknown selected engine",root464,"unknown");
