 static string DigestMinimal(string root){string html=File.ReadAllText(Path.Combine(root,"index.html"));var match=Regex.Match(html,"<script\\b(?=[^>]*\\btype=['\"]module['\"])[^>]*\\bsrc=['\"]([^'\"]+)['\"]",RegexOptions.IgnoreCase);string main=Regex.Split(match.Groups[1].Value,"[?#]")[0].TrimStart('.','/');return Files.HashText(Files.Hash(Path.Combine(root,"index.html"))+Files.Hash(Path.Combine(root,"webgal-engine.json"))+Files.Hash(Files.Under(root,main)));}
